sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?title ?director ?birthDate
WHERE {
  VALUES ?film { dbr:Final_Destination_3 dbr:Emily_Brontë's_Wuthering_Heights }

  # title (prefer dbp:name)
  OPTIONAL { ?film dbp:name ?title . }
  OPTIONAL { ?film dbo:title ?title . }

  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?director . }

  # director's birth date (prefer dbp:birthDate)
  OPTIONAL { ?director dbp:birthDate ?birthDate . }
  OPTIONAL { ? directors dbo:birthDate ?birthDate . }
}
LIMIT 100

